actions.script:
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
def uri = ec.web?.request?.requestURI ?: ''
def zenithIndex = uri.indexOf('/zenith/')
kitchenAction = (zenithIndex > 0 ? uri.substring(0, zenithIndex) : '') +
    '/zenith/pos/Kitchen/KitchenDisplay/updateStatus'
kitchenToken = ec.web?.sessionToken ?: ''
def kotQuery = ec.entity.find("zenith.erp.pos.KotView")
kotQuery.condition('organizationPartyId', org && org != '_NA_' ? org : '__NO_ORGANIZATION__')
def statuses=['KotNew','KotPreparing','KotReady']
if (!(filterStatus in statuses)) filterStatus=''
def allActive=kotQuery.condition('statusId','in',statuses).orderBy('-kotDate,kotId').list()
newCount=allActive.count { it.statusId=='KotNew' }
preparingCount=allActive.count { it.statusId=='KotPreparing' }
readyCount=allActive.count { it.statusId=='KotReady' }
activeKots=filterStatus ? allActive.findAll { it.statusId==filterStatus } : allActive
kotItemsMap=activeKots ? ec.entity.find('zenith.erp.pos.KotItem').condition('kotId','in',activeKots*.kotId)
    .orderBy('kotItemSeqId').list().groupBy { it.kotId } : [:]
kitchenPageUrl=kitchenAction.substring(0,kitchenAction.lastIndexOf('/'))
